import React from "react";
import { clsx } from "clsx";

import { TableClasses } from "../table.styles";

export const TableToolbar = (props: React.HTMLAttributes<HTMLDivElement>) => {
  return <div {...props} className={clsx(TableClasses.toolbar, props.className)} />;
};

TableToolbar.displayName = "Table.Toolbar";

export const TableToolbarTrailing = (props: React.HTMLAttributes<HTMLDivElement>) => {
  return <div {...props} className={clsx(TableClasses.toolbarTrailing, props.className)} />;
};

TableToolbarTrailing.displayName = "Table.ToolbarTrailing";
